#!/usr/bin/env python3
"""
Round 187o (culprits), 5 October 2026. Needs round 186o.

The Glass Garden basemap taken out.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 187o (5 October)\n\nNeeds round 186o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Owner: delete the Glass Garden basemap altogether. Taken out whole, as 182b\n  did for Aqua and Glass house: its block (LUMEN, lumenPaintPixels and its\n  Web Workers, the lumenpaint protocol, its outline-lumen-... layers, sky,\n  the lumenAura canvas and its switch), its menu line, THEMED_NAMES.lumen and\n  the "lumen" checks in themedWhich and themedSync. Rounds 183b and 184b\n  leave nothing behind; their test blocks are gone and a check says no\n  "lumen" or "Glass Garden" is left. The menu is Jurassic, Atlas, Woodlands,\n  Bioluminescent, Earth at Night, Hell, Standard. The basemap choice is not\n  remembered between visits, so no one is left on a missing basemap.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round187o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 186o" not in h.read_text(encoding="utf-8"):
        sys.exit("round187o: round 186o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round187o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round187o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round187o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
